"""Identification-type folds: Hodge = k<a>, Podge generated by g_ij = a^i u a^j - kappa_ij(a),
kappa(s,t) = C(s,t)/((1-sa)(1-ta)), C_00 = 0.  P defined via canonical factorization; complement <=> P(any product of g) = 0."""
import sympy as sp, itertools, functools, sys
def make(Cfun):
    """Cfun(i,j) -> coefficient C_ij (sympy expr)."""
    @functools.lru_cache(None)
    def kappa(i, j):  # dict m -> coeff (polynomial in a)
        r = {}
        for i2 in range(i + 1):
            for j2 in range(j + 1):
                c = Cfun(i2, j2)
                if c != 0:
                    m = i - i2 + j - j2; r[m] = sp.expand(r.get(m, 0) + c)
        return {m: v for m, v in r.items() if v != 0}
    def gen(i, j):  # element as dict word -> coeff
        r = {'a' * i + 'u' + 'a' * j: sp.Integer(1)}
        for m, v in kappa(i, j).items(): r['a' * m] = r.get('a' * m, 0) - v
        return r
    def mul(A, B):
        r = {}
        for w1, c1 in A.items():
            for w2, c2 in B.items():
                w = w1 + w2; r[w] = sp.expand(r.get(w, 0) + c1 * c2)
        return {w: c for w, c in r.items() if c != 0}
    def blocks(w): return [len(b) for b in w.split('u')]
    @functools.lru_cache(None)
    def P(w):  # returns dict m -> coeff  (element a^m of the Hodge)
        if 'u' not in w: return {len(w): sp.Integer(1)}
        bl = blocks(w); k = len(bl) - 1
        facs = [gen(bl[t], 0) for t in range(k - 1)] + [gen(bl[k - 1], bl[k])]
        prod = functools.reduce(mul, facs)
        res = {}
        for ww, c in prod.items():
            if ww == w: continue
            for m, v in P(ww).items(): res[m] = sp.expand(res.get(m, 0) - c * v)
        return {m: v for m, v in res.items() if v != 0}
    def Pel(E):
        res = {}
        for w, c in E.items():
            for m, v in P(w).items(): res[m] = sp.expand(res.get(m, 0) + c * v)
        return {m: v for m, v in res.items() if v != 0}
    return gen, mul, Pel, P
def products(N):
    gens = [(i, j) for i in range(N) for j in range(N) if i + j + 1 <= N]
    def rec(rem, cur):
        if cur: yield tuple(cur)
        for (i, j) in gens:
            if i + j + 1 <= rem: yield from rec(rem - i - j - 1, cur + [(i, j)])
    yield from rec(N, [])
def obstructions(Cfun, N):
    gen, mul, Pel, P = make(Cfun); eqs = set()
    for seq in products(N):
        if len(seq) < 2: continue
        E = functools.reduce(mul, [gen(i, j) for i, j in seq])
        for m, v in Pel(E).items():
            v = sp.factor(v)
            if v != 0: eqs.add(v)
    return eqs
if __name__ == '__main__':
    N = int(sys.argv[1]); D = N - 1
    Cs = {(i, j): sp.Symbol(f'C{i}{j}') for i in range(D + 1) for j in range(D + 1) if 0 < i + j <= D}
    eqs = obstructions(lambda i, j: Cs.get((i, j), 0), N)
    print(f"N={N}: {len(eqs)} distinct obstruction polynomials in {len(Cs)} unknowns")
    for e in sorted(eqs, key=lambda e: (sp.total_degree(e), str(e)))[:40]: print("   ", e)
